// 1. Tomamos la respuesta de la IA
let raw = items[0].json.output;

// 2. NUEVO: Detectar si ya es un objeto parseado
let parsed;
if (typeof raw === 'object' && raw !== null) {
  // Ya viene parseado, lo usamos directamente
  parsed = raw;
} else {
  // Es string, necesitamos limpiarlo y parsearlo
  let cleaned = raw
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  // 3. Eliminar texto antes del primer { y después del último }
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error('No se encontró JSON válido en la respuesta');
  }
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);

  // 4. Limpiar comas mal colocadas
  cleaned = cleaned
    .replace(/\}\s*,\s*,/g, '},')
    .replace(/\]\s*,\s*,/g, '],')
    .replace(/,(\s*[\]}])/g, '$1');

  // 5. Parseamos a objeto JS
  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    console.error('=== JSON QUE FALLÓ ===');
    console.error(cleaned.substring(0, 1000));
    throw new Error(`Error parseando JSON de la IA: ${error.message}`);
  }
}

// 6. Validación: verificar que resultados existe y es array
if (!parsed.resultados || !Array.isArray(parsed.resultados)) {
  throw new Error('La respuesta no contiene un array "resultados" válido');
}

const resultados = parsed.resultados;

// 7. Validación: verificar que no esté vacío
if (resultados.length === 0) {
  throw new Error('El array de resultados está vacío');
}

// 8. Validar y auto-corregir cada resultado
const requiredFields = ['id', 'titulo', 'tipo', 'palabraClave', 'justificacion', 'pertinencia', 'criterios'];
const errores = [];

const resultadosCorregidos = resultados.map((r, index) => {
  const missing = requiredFields.filter(field => !(field in r));

  if (missing.length > 0) {
    errores.push(`Recurso ${index + 1} (ID: ${r.id || '?'}): faltan campos ${missing.join(', ')}`);
  }

  // Auto-corregir criterios si faltan
  if (!r.criterios || typeof r.criterios !== 'object') {
    r.criterios = { c1: 0, c2: 0, c3: 0, c4: 0, c5: 0, c6: 0 };
    errores.push(`Recurso ${index + 1} (ID: ${r.id}): criterios faltantes, se asignaron 0s`);
  } else {
    ['c1', 'c2', 'c3', 'c4', 'c5', 'c6'].forEach(c => {
      if (!(c in r.criterios)) {
        r.criterios[c] = 0;
      }
    });
  }

  // Auto-calcular pertinencia si falta o es inválida
  if (typeof r.pertinencia !== 'number' || r.pertinencia < 0 || r.pertinencia > 10) {
    const calc = Math.round(
      (r.criterios.c1 * 0.25) +
      (r.criterios.c2 * 0.25) +
      (r.criterios.c3 * 0.20) +
      (r.criterios.c4 * 0.15) +
      (r.criterios.c5 * 0.10) +
      (r.criterios.c6 * 0.05)
    );
    r.pertinencia = Math.max(0, Math.min(10, calc));
    errores.push(`Recurso ${index + 1} (ID: ${r.id}): pertinencia auto-calculada = ${r.pertinencia}`);
  }

  // Asegurar que otros campos existan
  r.id = r.id || 'unknown';
  r.titulo = r.titulo || 'Sin título';
  r.tipo = r.tipo || 'Desconocido';
  r.palabraClave = r.palabraClave || '';
  r.justificacion = r.justificacion || 'Sin justificación disponible';

  return r;
});

// 9. Mostrar advertencias si las hay
if (errores.length > 0) {
  console.warn('=== ADVERTENCIAS DE VALIDACIÓN ===');
  errores.forEach(e => console.warn(e));
  console.warn(`Total recursos procesados: ${resultadosCorregidos.length}`);
}

// 10. Normalizar: 1 item por resultado
return resultadosCorregidos.map(r => ({
  json: r
}));

return items.map((item, index) => {
  const r = item.json;

  // 1. Buscar criterios (manejo robusto)
  let criterios = null;

  // Caso ideal: ya existe r.criterios
  if (r.criterios && typeof r.criterios === 'object') {
    criterios = r.criterios;
  }

  // Buscar por estructura si no existe con ese nombre
  if (!criterios) {
    for (const [key, value] of Object.entries(r)) {
      if (
        value &&
        typeof value === 'object' &&
        ['c1','c2','c3','c4','c5','c6'].every(k => k in value)
      ) {
        criterios = value;
        delete r[key]; // elimina el nombre incorrecto
        break;
      }
    }
  }

  // Fallback ultra seguro
  criterios = criterios || {
    c1: 0, c2: 0, c3: 0, c4: 0, c5: 0, c6: 0
  };

  // 2. Validar y corregir pertinencia NUEVAMENTE (por si acaso)
  let pertinencia = r.pertinencia;

  if (typeof pertinencia !== 'number' || pertinencia < 1 || pertinencia > 10) {
    // Recalcular desde criterios
    pertinencia = Math.round(
      (criterios.c1 * 0.25) +
      (criterios.c2 * 0.25) +
      (criterios.c3 * 0.20) +
      (criterios.c4 * 0.15) +
      (criterios.c5 * 0.10) +
      (criterios.c6 * 0.05)
    );
    pertinencia = Math.max(1, Math.min(10, pertinencia));
    console.warn(`Item ${index}: pertinencia recalculada = ${pertinencia}`);
  }

  // 3. Mapeo final con validaciones
  return {
    json: {
      id: r.id || 'unknown',
      titulo: r.titulo || 'Sin título',
      tipo: r.tipo || 'Desconocido',
      palabra_clave: r.palabraClave || '',
      pertinencia: pertinencia,
      c1: parseInt(criterios.c1) || 0,
      c2: parseInt(criterios.c2) || 0,
      c3: parseInt(criterios.c3) || 0,
      c4: parseInt(criterios.c4) || 0,
      c5: parseInt(criterios.c5) || 0,
      c6: parseInt(criterios.c6) || 0,
      justificacion: r.justificacion || 'Sin justificación',
      numero_ejecucion: $('Start').first().json.numero_ejecucion || 'unknown'
    }
  };
});

const systemPrompt = `
Eres un evaluador académico experto en diseño instruccional y evaluación curricular.

REGLAS ABSOLUTAS DE FORMATO:
1. Respondes ÚNICAMENTE con JSON válido RFC 8259
2. NUNCA incluyas markdown (~~~json), texto explicativo, ni comentarios
3. TODOS los objetos deben tener TODAS estas llaves obligatorias:
   - id (string)
   - titulo (string)
   - tipo (string)
   - palabraClave (string)
   - justificacion (string de 40-60 palabras)
   - pertinencia (número entero 1-10)
   - criterios (objeto con c1, c2, c3, c4, c5, c6 como números 0-10)

4. VALIDACIÓN PREVIA A RESPONDER:
   ✓ Cuenta cuántos recursos se te piden evaluar (N)
   ✓ Verifica que tu array "resultados" tenga exactamente N elementos
   ✓ Verifica que cada elemento tenga las 7 llaves obligatorias
   ✓ Verifica que no haya comas mal colocadas

5. ESTRUCTURA EXACTA (no alteres nombres de llaves):
{
  "resultados": [
    {
      "id": "valor",
      "titulo": "valor",
      "tipo": "valor",
      "palabraClave": "valor",
      "justificacion": "40-60 palabras",
      "pertinencia": 8,
      "criterios": {
        "c1": 9,
        "c2": 8,
        "c3": 7,
        "c4": 8,
        "c5": 9,
        "c6": 7
      }
    }
  ]
}

Comienza tu respuesta DIRECTAMENTE con el carácter {
NO incluyas NADA antes ni después del JSON.
`;

const userPrompt = items[0].json.chatInput;

return [
  {
    json: {
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ]
    }
  }
];
